585	    /// Lookup an inode in the parent directory with the given name.
586	    ///
587	    /// Updates the parent inode to be in sync with the client, but does
588	    /// not add new inodes to the superblock. The caller is responsible
589	    /// for calling [`remember()`] if that is required.
590	    pub async fn lookup_by_name<OC: ObjectClient>(
591	        &self,
592	        client: &OC,
593	        parent_ino: InodeNo,
594	        name: &OsStr,
595	        allow_cache: bool,
596	    ) -> Result<LookedUp, InodeError> {
597	        let name = name
598	            .to_str()
599	            .ok_or_else(|| InodeError::InvalidFileName(name.to_owned()))?;
600	
601	        // This should be impossible, but just to be safe, explicitly reject lookups to files that
602	        // end with '/', since they could be shadowed by directories.
603	        if name.ends_with('/') {
604	            return Err(InodeError::InvalidFileName(name.into()));
605	        }
606	
607	        let lookup = if allow_cache {
608	            self.cache_lookup(parent_ino, name)
609	        } else {
610	            None
611	        };
612	
613	        let lookup = match lookup {
614	            Some(lookup) => lookup,
615	            None => {
616	                let remote = self.remote_lookup(client, parent_ino, name).await?;
617	                self.update_from_remote(parent_ino, name, remote)?
618	            }
619	        };
620	
621	        lookup.inode.verify_child(parent_ino, name.as_ref())?;
622	        Ok(lookup)
623	    }
