[metadata] {"type": "create", "filePath": "/workspace/repo/mountpoint-s3/src/inode/negative_cache.rs", "content": "//! A cache of negative (file-not-found) lookups.
//!
//! When a `lookup` fails to find an object in S3, we remember that failure here so that repeated
//! lookups for the same non-existent path don't each trigger a fresh (and relatively expensive)
//! pair of HeadObject/ListObjects requests. Entries expire after a TTL and the cache is bounded in
//! size, evicting the oldest entries first.

use std::time::{Duration, Instant};

use linked_hash_map::LinkedHashMap;

use super::InodeNo;
use crate::sync::Mutex;

/// Key identifying a negative cache entry: the parent directory and the (missing) child name.
type CacheKey = (InodeNo, String);

/// A bounded, TTL'd cache of failed lookups.
#[derive(Debug)]
pub struct NegativeCache {
    max_size: usize,
    ttl: Duration,
    /// Maps a missing (parent, name) to the [Instant] at which the negative entry expires. Ordered
    /// by insertion so we can evict the oldest entries when the cache is full.
    entries: Mutex<LinkedHashMap<CacheKey, Instant>>,
}

impl NegativeCache {
    pub fn new(max_size: usize, ttl: Duration) -> Self {
        Self {
            max_size,
            ttl,
            entries: Mutex::new(LinkedHashMap::new()),
        }
    }

    /// Returns `true` if we have a non-expired negative entry for the given path. Expired entries
    /// are removed as a side effect.
    pub fn contains(&self, parent_ino: InodeNo, name: &str) -> bool {
        if self.max_size == 0 {
            return false;
        }
        let key = (parent_ino, name.to_owned());
        let mut entries = self.entries.lock().unwrap();
        let valid = match entries.get(&key) {
            Some(expiry) => *expiry >= Instant::now(),
            None => return false,
        };
        if !valid {
            entries.remove(&key);
        }
        valid
    }

    /// Record that the given path was not found, so future lookups can be served from the cache.
    pub fn insert(&self, parent_ino: InodeNo, name: &str) {
        if self.max_size == 0 {
            return;
        }
        let expiry = Instant::now()
            .checked_add(self.ttl)
            .expect("64-bit time shouldn't overflow");
        let key = (parent_ino, name.to_owned());
        let mut entries = self.entries.lock().unwrap();
        // Re-inserting moves the entry to the back (most recently inserted).
        entries.insert(key, expiry);
        while entries.len() > self.max_size {
            entries.pop_front();
        }
    }

    /// Remove any negative entry for the given path, e.g. because it was just discovered to exist.
    pub fn remove(&self, parent_ino: InodeNo, name: &str) {
        if self.max_size == 0 {
            return;
        }
        let key = (parent_ino, name.to_owned());
        self.entries.lock().unwrap().remove(&key);
    }
}
